#include <set>

class stringx
{
public:
  stringx();
  stringx(const stringx&);
  ~stringx();
  bool operator<(const stringx&) const;
private:
  void* data;
};

void* operator new(unsigned int, unsigned int, const char*, int);
#define NEW new(0, __FILE__, __LINE__)

class material
{
public:
  material(const material&);
  const stringx& get_instance_name() const { return material_name; }
private:
  stringx material_name;
  char remainder[256];
};

template <class T>
class instance_bank
{
public:
  struct ref_t
  {
    stringx label;
    T* ptr;
    unsigned int count;
    ref_t(const stringx& _label) : label(_label), ptr(0), count(0) {}
    ref_t(const stringx& _label, T* _ptr) : label(_label), ptr(_ptr), count(1) {}
  };
  class less_by_label : public binary_function<const ref_t*, const ref_t*, bool>
  {
  public:
    bool operator()(const ref_t* a, const ref_t* b) const { return a->label < b->label; }
  };
  class less_by_ptr : public binary_function<const ref_t*, const ref_t*, bool>
  {
  public:
    bool operator()(const ref_t* a, const ref_t* b) const { return a->ptr < b->ptr; }
  };
  typedef set<ref_t*, less_by_label, malloc_alloc> lref_set;
  typedef set<ref_t*, less_by_ptr, malloc_alloc> pref_set;
  lref_set refs_by_label;
  pref_set refs_by_ptr;
  T* new_instance(const T& copy);
  void insert(const stringx& label, T* ptr)
  {
    ref_t* r = NEW ref_t(label, ptr);
    refs_by_label.insert(r);
    refs_by_ptr.insert(r);
  }
};

template <class T>
T* instance_bank<T>::new_instance(const T& copy)
{
  ref_t copy_name_ref(copy.get_instance_name());
  lref_set::iterator i = refs_by_label.find(&copy_name_ref);
  if (i == refs_by_label.end())
  {
    T* new_T = NEW T(copy);
    insert(copy.get_instance_name(), new_T);
    return new_T;
  }
  else
  {
    ++(*i)->count;
    return (*i)->ptr;
  }
}

template material* instance_bank<material>::new_instance(const material&);
